function removeTokenIdAtIndex(uint256 _index) external onlyOwner {
    uint256 tokenId = tokenIds[_index];
    tokenIds[_index] = tokenIds[tokenIds.length - 1];
    tokenIds.pop();
    // remove mapping to pool
    delete tokenIdToPool[tokenId];
}

